package validator

import "testing"

// Expected values generated by Python: str(json.loads(literal)).
func TestBizDataNumberStrMatchesPython(t *testing.T) {
	cases := []struct{ lit, want string }{
		{"1164862", "1164862"},
		{"0", "0"},
		{"-5", "-5"},
		{"1.0", "1.0"},
		{"1.5", "1.5"},
		{"0.1", "0.1"},
		{"100.0", "100.0"},
		{"1e5", "100000.0"},
		{"1E-5", "1e-05"},
		{"1.5e-7", "1.5e-07"},
		{"123456789012345678", "123456789012345678"},
		{"12345678901234567890123", "12345678901234567890123"},
		{"1e16", "1e+16"},
		{"1e15", "1000000000000000.0"},
		{"9999999999999999.0", "1e+16"},
		{"0.0001", "0.0001"},
		{"0.00001", "1e-05"},
		{"3.14159", "3.14159"},
		{"-0.0", "-0.0"},
		{"2.5e+20", "2.5e+20"},
	}
	for _, c := range cases {
		data, err := decodeBizData(`{"v": ` + c.lit + `}`)
		if err != nil {
			t.Fatalf("%s: %v", c.lit, err)
		}
		if got := pythonStr(data["v"]); got != c.want {
			t.Errorf("literal %s: got %q, want %q", c.lit, got, c.want)
		}
	}
}

func TestToStringIntegerLiteralNotExponent(t *testing.T) {
	tpl := `{"gas": {{ d.gas | toString }}}`
	got, err := NewStatementBuilder(tpl).Build(`{"d": {"gas": 1164862}}`)
	if err != nil {
		t.Fatal(err)
	}
	if want := `{"gas":"1164862"}`; got != want {
		t.Errorf("got %s, want %s", got, want)
	}
}
